<x-layouts.app><a class="button" href="{{ route('devices.edit',$device) }}">Edit device</a><h1>{{ $device->name }}</h1><div class="card"><p><b>Site:</b> {{ $device->site->name }}</p><p><b>Type:</b> {{ $device->type->name }}</p><p><b>Static IP:</b> {{ $device->management_ip }}</p><p><b>MAC address:</b> {{ $device->mac_address }}</p><p><b>Default gateway:</b> {{ $device->default_gateway }}</p><p><b>Subnet mask:</b> {{ $device->subnet_mask }}</p><p><b>Profile:</b> {{ $device->monitoringProfile?->name ?? 'Not configured' }}</p><p><b>Status:</b> {{ $device->status }}</p><p><b>Notes:</b> {{ $device->notes }}</p></div></x-layouts.app>
